class Solution {
public:
    string compressedString(string word) {
        string comp;
        int n = (int)word.size();
        int i = 0;
        while (i < n) {
            char c = word[i];
            int count = 0;
            while (i < n && word[i] == c && count < 9) {
                ++count;
                ++i;
            }
            comp.push_back(char('0' + count));
            comp.push_back(c);
        }
        return comp;
    }
};
